const clean = (v, fallback = "") =>
  v === undefined || v === null || String(v).trim() === ""
    ? fallback
    : String(v).replace(/\s+/g, " ").trim();

const num = (v) => {
  if (v === undefined || v === null || v === "") return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
};

const level = (x, low, mid, high) =>
  x === null ? "" : x < 0.33 ? low : x < 0.66 ? mid : high;

const seen = new Set();
const out = [];

for (const item of $input.all()) {
  const r = item.json;
  const track_id = clean(r.track_id || r.id);
  if (!track_id || seen.has(track_id)) continue;
  seen.add(track_id);

  const title = clean(r.track_name, "Ukendt titel");
  const artist = clean(r.track_artist, "Ukendt kunstner");
  const genre = clean(r.playlist_genre, "Ukendt genre");
  const subgenre = clean(r.playlist_subgenre, "Ukendt subgenre");
  const album = clean(r.track_album_name, "Ukendt album");
  const album_id = clean(r.track_album_id, `${album}|${artist}`);
  const year = parseInt(String(r.track_album_release_date ?? "").substring(0, 4), 10);
  const release_year = Number.isFinite(year) ? year : null;

  const energy = num(r.energy);
  const danceability = num(r.danceability);
  const valence = num(r.valence);
  const acousticness = num(r.acousticness);

  const words = [
    level(energy, "rolig, lav energi", "middel energi", "energisk, høj energi"),
    level(danceability, "ikke særlig dansbar", "nogenlunde dansbar", "meget dansbar"),
    level(valence, "melankolsk, trist stemning", "neutral stemning", "glad, positiv stemning"),
    level(acousticness, "elektronisk lyd", "", "akustisk lyd"),
  ].filter(Boolean).join(", ");

  const vibe_description =
    `${genre} (${subgenre}) af ${artist} fra albummet ${album}` +
    `${release_year ? ` (${release_year})` : ""}. Stemning: ${words}.`;

  out.push({ json: {
    track_id, title, artist, genre, subgenre,
    subgenre_id: `${genre}/${subgenre}`,
    album, album_id, release_year,
    popularity: num(r.track_popularity),
    energy, danceability, valence,
    vibe_description,
    chunk_text: `Titel: ${title}. Kunstner: ${artist}. ${vibe_description}`,
  }});
}
return out;

const rows = $input.all().map(i => i.json);
return [{ json: {
  rows,
  embeddingBody: { model: "text-embedding-3-small", input: rows.map(r => r.chunk_text) }
}}];

const rows = $('Code B').first().json.rows;
const data = [...$json.data].sort((a, b) => a.index - b.index);

if (data.length !== rows.length) {
  throw new Error(`Fik ${data.length} embeddings for ${rows.length} rækker`);
}
rows.forEach((r, i) => {
  r.embedding = data[i].embedding;
  if (r.embedding.length !== 1536) throw new Error(`Forkert dimension: ${r.title}`);
});

const statement = `
UNWIND $rows AS row
MERGE (t:Track {track_id: row.track_id})
SET t.title = row.title,
    t.release_year = row.release_year,
    t.popularity = row.popularity,
    t.energy = row.energy,
    t.danceability = row.danceability,
    t.valence = row.valence,
    t.vibe_description = row.vibe_description,
    t.chunk_text = row.chunk_text,
    t.embedding = row.embedding,
    t.source = 'high_popularity_spotify_data.csv'

MERGE (a:Artist {name: row.artist})
MERGE (t)-[:PERFORMED_BY]->(a)

MERGE (g:Genre {name: row.genre})
MERGE (t)-[:IN_GENRE]->(g)
MERGE (a)-[:PLAYS_GENRE]->(g)

MERGE (s:Subgenre {id: row.subgenre_id})
SET s.name = row.subgenre
MERGE (t)-[:HAS_SUBGENRE]->(s)
MERGE (s)-[:PART_OF]->(g)

MERGE (al:Album {album_id: row.album_id})
SET al.name = row.album, al.release_year = row.release_year
MERGE (t)-[:ON_ALBUM]->(al)

FOREACH (_ IN CASE WHEN row.release_year IS NULL THEN [] ELSE [1] END |
  MERGE (y:Year {value: row.release_year})
  MERGE (al)-[:RELEASED_IN]->(y)
)
RETURN count(t) AS imported
`;

return [{ json: { neo4jBody: { statements: [{ statement, parameters: { rows } }] } } }];
